scenario.en:
// app/pricing/page.tsx — no time-based revalidate, tags only
const prices = await fetch(CMS_URL, {
  next: { tags: ['pricing'] },
});

// app/api/cms-webhook/route.ts
import { revalidateTag } from 'next/cache';
export async function POST() {
  revalidateTag('pricing'); // ran on pod B at 12:00
  return Response.json({ ok: true });
}
// pods A, B, C — each with its own .next/cache on local disk

